/* From Uiverse.io by gharsh11032000 - Tags: gradient, checkbox, toggle, click effect */
/* Hide the default checkbox */
.__UIV_SCOPE__ .container input {
  position: absolute;
  opacity: 0;
  cursor: pointer;
  height: 0;
  width: 0;
}

.__UIV_SCOPE__ .container {
  display: block;
  position: relative;
  cursor: pointer;
  font-size: 20px;
  user-select: none;
  overflow: hidden;
}

/* Create a custom checkbox */
.__UIV_SCOPE__ .checkmark {
  position: relative;
  top: 0;
  left: 0;
  height: 1.3em;
  width: 1.3em;
  border: 2px solid #414141;
  transition: all 0.4s cubic-bezier(0.23, 1, 0.320, 1);
}

/* When the checkbox is checked */
.__UIV_SCOPE__ .container input:checked ~ .checkmark {
  border-image: linear-gradient(-45deg, #f89b29 0%, #ff0f7b 100% );
  border-image-slice: 1;
}

/* Create the checkmark/indicator (hidden when not checked) */
.__UIV_SCOPE__ .checkmark:after {
  content: "";
  position: absolute;
}

/* Style the checkmark/indicator */
.__UIV_SCOPE__ .container .checkmark:after {
  left: 0.45em;
  top: -2em;
  width: 0.25em;
  height: 0.5em;
  border: solid white;
  border-width: 0 0.15em 0.15em 0;
  transform: rotate(45deg);
  transition: all 0.6s cubic-bezier(0.23, 1, 0.320, 1);
}

.__UIV_SCOPE__ .container .checkmark::before {
  left: 0.45em;
  top: 2em;
  width: 0.25em;
  height: 0.5em;
  border: solid white;
  border-width: 0 0.15em 0.15em 0;
  transform: rotate(45deg);
}

/* Show the checkmark when checked */
.__UIV_SCOPE__ .container input:checked ~ .checkmark:after {
  top: 0.25em;
}
